import collections

class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be 1 or greater")
        self.capacity = capacity
        # key: value のペアを保持し、挿入順序（またはアクセス順）を維持するためにOrderedDictを使用する
        self.cache = collections.OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1

        # 存在する場合、値を読み出す。
        value = self.cache[key]

        # 最新の使用要素としてマークするために、要素をエンドに移動させる (O(1))。
        self.cache.move_to_end(key)
        return value

    def put(self, key, value):
        if key in self.cache:
            # 既存のキーの場合、値を更新し、最新要素としてマークする。
            self.cache[key] = value
            self.cache.move_to_end(key)
        else:
            # 新規挿入の場合、容量オーバーチェックを行う。
            if len(self.cache) == self.capacity:
                # 容量オーバーの場合、最も長く使っていない要素（アンオーダーの先頭）を削除する (O(1))。
                # popitem(last=False) は FIFO の要素を取り除く。
                self.cache.popitem(last=False)

            # 新しい要素を挿入し、自動的に最新要素となる。
            self.cache[key] = value
        # 戻り値は None
        return None

    def __len__(self):
        return len(self.cache)
